4	describe("claim-office CLI", () => {
5	  it("should write a results array with one entry per step to stdout and exit 0", () => {
6	    const input = JSON.stringify({
7	      customer: { yearsWithMHPCO: 5 },
8	      steps: [
9	        {
10	          op: "quote",
11	          items: [
12	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
13	          ],
14	        },
15	        {
16	          op: "claim",
17	          policy: 0,
18	          incident: {
19	            cause: "fire",
20	            damages: [{ itemType: "amulet", amount: 200 }],
21	          },
22	        },
23	      ],
24	    });
25	
26	    const { exitCode, stdout } = runCli(input);
27	
28	    expect(exitCode).toBe(0);
29	    expect(JSON.parse(stdout).results).toHaveLength(2);
30	  });
31	  it("should write the premium for a quote step", () => {
32	    const input = JSON.stringify({
33	      customer: { yearsWithMHPCO: 5 },
34	      steps: [
35	        {
36	          op: "quote",
37	          items: [
38	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
39	          ],
40	        },
41	      ],
42	    });
43	
44	    const { stdout } = runCli(input);
45	
46	    expect(JSON.parse(stdout).results[0]).toEqual({ premium: 59 });
