51	      customer: { yearsWithMHPCO: 5 },
52	      steps: [
53	        {
54	          op: "quote",
55	          items: [
56	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
57	          ],
58	        },
59	        {
60	          op: "claim",
61	          policy: 0,
62	          incident: {
63	            cause: "fire",
64	            damages: [{ itemType: "amulet", amount: 200 }],
65	          },
66	        },
67	      ],
68	    });
69	
70	    const { stdout } = runCli(input);
71	
72	    expect(JSON.parse(stdout).results).toEqual([
73	      { premium: 59 },
74	      { payout: 100, remainingCap: 1100 },
