77	  it("should exit with a non-zero code and write to stderr when runScenario rejects the scenario", () => {
78	    const input = JSON.stringify({
79	      customer: { yearsWithMHPCO: 5 },
80	      steps: [
81	        {
82	          op: "quote",
83	          items: [
84	            {
85	              type: "broomstick",
